                    end
                end
                if isempty(mem)
                    error("mat2ppt:ValueError", "value is not a member of MSO_LANGUAGE_ID");
                end
            end
            if strlength(string(mem.xml_value)) == 0
                error("mat2ppt:ValueError", "MSO_LANGUAGE_ID.%s has no XML representation", mem.name);
            end
            x = char(mem.xml_value);
        end
    end
end
